// サーキットを建てる — the circuit, as something you can look at.
//
// Every shape in here is generated from the frames in kart-track-data.js, which is the
// same list the kart drives on and the server judges laps by. Nothing is placed by eye: if
// the road bends, the kerb, the barrier, the grass and the trees bend with it, because
// they are all built from the same walk round the lap. That is the only way a track this
// size stays honest through tuning.
//
// It is also built to be cheap. The road, the kerbs, the barriers and the ground are four
// meshes for the whole circuit rather than four per corner, and everything that repeats —
// trees, stands, item boxes — is an InstancedMesh. A classroom iPad has one GPU and
// twelve karts to draw on it.
import * as THREE from './three.module.js';

const col = (hex) => new THREE.Color(hex);

// Push one quad as two triangles.
function quad(pos, idx, a, b, c, d) {
  const base = pos.length / 3;
  for (const p of [a, b, c, d]) pos.push(p[0], p[1], p[2]);
  idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
}
function paint(colours, c, n = 4) {
  for (let i = 0; i < n; i += 1) colours.push(c.r, c.g, c.b);
}

// The road, its kerbs, its lines and the ground it sits on — one pass round the lap.
function surfaces(track, theme) {
  const road = { pos: [], idx: [], col: [] };
  const kerb = { pos: [], idx: [], col: [] };
  const land = { pos: [], idx: [], col: [] };
  const tarmac = col(0x6e6e79);
  const tarmacDark = col(0x63636e);
  const line = col(0xf2efe4);
  const kerbA = col(0xd7534a);
  const kerbB = col(0xf3efe1);
  const grass = col(theme.ground || 0x6f9a5a);
  const grassDark = col(0x5d8850);
  const sand = col(theme.sand || 0xe0cfa0);

  const n = track.frames.length;
  // Points across the road at one frame, leaning with the corner.
  const edge = (f, o) => {
    const lean = Math.sin(f.bank) * o;         // the far side of a banked corner is higher
    return [f.x + f.nx * o, f.y - lean, f.z + f.nz * o];
  };

  for (let i = 0; i < n; i += 1) {
    const f = track.frames[i];
    const g = track.frames[(i + 1) % n];
    const hw = f.w / 2;
    const hg = g.w / 2;
    // The tarmac, in three strips so the centre line and the edge lines are geometry
    // rather than a texture — a texture at this size is a download and a blurry line.
    const lanes = [
      [-hw, -hw + 0.45, kerbB, kerbB],
      [-hw + 0.45, -0.22, tarmac, tarmacDark],
      [-0.22, 0.22, line, line],
      [0.22, hw - 0.45, tarmacDark, tarmac],
      [hw - 0.45, hw, kerbB, kerbB],
    ];
    for (const [a, b, c1, c2] of lanes) {
      const sa = a / hw;
      const sb = b / hw;
      quad(road.pos, road.idx, edge(f, sa * hw), edge(f, sb * hw), edge(g, sb * hg), edge(g, sa * hg));
      // A faint stripe every few metres, so speed reads on the road itself.
      const shade = (i % 8 < 4) ? c1 : c2;
      paint(road.col, shade);
    }

    // Kerbs on the corners, red and white, a little proud of the road.
    if (Math.abs(f.curv) > 0.006) {
      const side = f.curv > 0 ? -1 : 1;         // the inside of the corner
      const a = side * hw;
      const b = side * (hw + 1.5);
      const ga = side * hg;
      const gb = side * (hg + 1.5);
      const lift = 0.09;
      const p1 = edge(f, a); const p2 = edge(f, b);
      const p3 = edge(g, gb); const p4 = edge(g, ga);
      quad(kerb.pos, kerb.idx, [p1[0], p1[1] + lift, p1[2]], [p2[0], p2[1] + lift, p2[2]],
        [p3[0], p3[1] + lift, p3[2]], [p4[0], p4[1] + lift, p4[2]]);
      paint(kerb.col, (i % 6 < 3) ? kerbA : kerbB);
    }

    // The ground either side: a wide apron of grass that follows the road's height, so the
    // hill is a hill rather than a road floating over a flat field.
    for (const side of [-1, 1]) {
      const steps = [[hw, hw + 3, sand], [hw + 3, hw + 16, grass], [hw + 16, hw + 46, grassDark]];
      for (const [a, b, c] of steps) {
        const drop = (k) => Math.min(0, -(k - hw) * 0.06);   // it falls away from the road
        const p1 = edge(f, side * a); const p2 = edge(f, side * b);
        const p3 = edge(g, side * b); const p4 = edge(g, side * a);
        quad(land.pos, land.idx,
          [p1[0], f.y + drop(a) - 0.05, p1[2]], [p2[0], f.y + drop(b) - 0.05, p2[2]],
          [p3[0], g.y + drop(b) - 0.05, p3[2]], [p4[0], g.y + drop(a) - 0.05, p4[2]]);
        paint(land.col, c);
      }
    }
  }
  return { road, kerb, land };
}

// Every surface here is drawn from both sides. The road, the kerbs and the apron are
// generated by walking the lap, and a quad's winding flips with which side of the road it
// is on — so half of them faced downwards and the first screenshot was a grid of karts
// floating over the sea. Two-sided costs nothing on flat ground and cannot be got wrong.
function meshFrom(data, { flat = false, side = THREE.DoubleSide } = {}) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(data.pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(
    // One colour per quad was pushed; expand it to the four corners.
    data.col.flatMap ? data.col : data.col, 3,
  ));
  g.setIndex(data.idx);
  g.computeVertexNormals();
  const m = new THREE.MeshLambertMaterial({ vertexColors: true, side, flatShading: flat });
  return new THREE.Mesh(g, m);
}

// The barrier: a low wall along the outside of the stretches that have one, in the same
// place the driving code bounces off. Built from the same `walled()` the physics asks.
function barriers(track) {
  const g = new THREE.Group();
  const pos = [];
  const idx = [];
  const cols = [];
  const white = col(0xf3efe1);
  const red = col(0xd7534a);
  const n = track.frames.length;
  for (let i = 0; i < n; i += 1) {
    const f = track.frames[i];
    const h = track.frames[(i + 1) % n];
    if (!track.walled(f.s) || !track.walled(h.s)) continue;
    for (const side of [-1, 1]) {
      const a = side * (f.w / 2 + 0.1);
      const b = side * (h.w / 2 + 0.1);
      const top = 1.15;
      const p1 = [f.x + f.nx * a, f.y, f.z + f.nz * a];
      const p2 = [h.x + h.nx * b, h.y, h.z + h.nz * b];
      quad(pos, idx, [p1[0], p1[1], p1[2]], [p1[0], p1[1] + top, p1[2]],
        [p2[0], p2[1] + top, p2[2]], [p2[0], p2[1], p2[2]]);
      paint(cols, (i % 4 < 2) ? white : red);
    }
  }
  if (!pos.length) return g;
  g.add(meshFrom({ pos, idx, col: cols }, { side: THREE.DoubleSide }));
  return g;
}

// The start: a gantry over the road with a chequered line under it.
function startLine(track) {
  const g = new THREE.Group();
  const f = track.at(0);
  const hw = f.w / 2;
  // The chequer.
  const squares = 14;
  for (let i = 0; i < squares; i += 1) {
    for (let j = 0; j < 2; j += 1) {
      const o = -hw + (i / squares) * f.w;
      const s = j * 1.6;
      const p = track.place(s, o + f.w / squares / 2);
      const m = new THREE.Mesh(
        new THREE.BoxGeometry(f.w / squares, 0.04, 1.6),
        new THREE.MeshLambertMaterial({ color: (i + j) % 2 ? 0x1b1b1f : 0xf3efe1 }),
      );
      m.position.set(p.x, p.y + 0.03, p.z);
      m.rotation.y = Math.atan2(f.tx, f.tz);
      g.add(m);
    }
  }
  // The gantry.
  const legMat = new THREE.MeshLambertMaterial({ color: 0x2f6b7f });
  for (const side of [-1, 1]) {
    const p = track.place(0, side * (hw + 1.6));
    const leg = new THREE.Mesh(new THREE.BoxGeometry(1.1, 8.5, 1.1), legMat);
    leg.position.set(p.x, p.y + 4.25, p.z);
    g.add(leg);
  }
  const mid = track.place(0, 0);
  const beam = new THREE.Mesh(new THREE.BoxGeometry(f.w + 4.4, 1.9, 1.2), legMat);
  beam.position.set(mid.x, mid.y + 8, mid.z);
  beam.rotation.y = Math.atan2(f.tx, f.tz) + Math.PI / 2;
  g.add(beam);
  const sign = new THREE.Mesh(new THREE.BoxGeometry(f.w * 0.55, 1.3, 0.2),
    new THREE.MeshBasicMaterial({ color: 0xffd166 }));
  sign.position.set(mid.x, mid.y + 8, mid.z + 0.7);
  sign.rotation.y = beam.rotation.y;
  g.add(sign);
  return g;
}

// The ramp: a wedge the kart drives up, in the place the physics throws it into the air.
function ramps(track) {
  const g = new THREE.Group();
  for (const j of track.jumps) {
    const f = track.at(j.s);
    const shape = new THREE.BufferGeometry();
    const hw = f.w / 2;
    const pos = [];
    const idx = [];
    const cols = [];
    const rise = 1.5;
    const a = track.place(j.s - 7, 0);
    const b = track.place(j.s, 0);
    const fa = track.at(j.s - 7);
    const fb = track.at(j.s);
    quad(pos, idx,
      [a.x + fa.nx * hw, a.y, a.z + fa.nz * hw], [a.x - fa.nx * hw, a.y, a.z - fa.nz * hw],
      [b.x - fb.nx * hw, b.y + rise, b.z - fb.nz * hw], [b.x + fb.nx * hw, b.y + rise, b.z + fb.nz * hw]);
    paint(cols, col(0xe0a04a));
    shape.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    shape.setAttribute('color', new THREE.Float32BufferAttribute(cols, 3));
    shape.setIndex(idx);
    shape.computeVertexNormals();
    g.add(new THREE.Mesh(shape, new THREE.MeshLambertMaterial({ vertexColors: true, side: THREE.DoubleSide })));
  }
  return g;
}

// Boost pads: chevrons painted on the road, pointing the way.
function pads(track) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x63c7ff, transparent: true, opacity: 0.85 });
  for (const b of track.boosts) {
    const f = track.at(b.s);
    for (let i = 0; i < 3; i += 1) {
      const p = track.place(b.s + i * 2.2, b.o);
      const m = new THREE.Mesh(new THREE.BoxGeometry(4.2, 0.05, 1.5), mat);
      m.position.set(p.x, p.y + 0.05, p.z);
      m.rotation.y = Math.atan2(f.tx, f.tz);
      g.add(m);
    }
  }
  return g;
}

// The scenery. Instanced, because a hundred palms is a hundred draw calls otherwise.
function scenery(track, theme) {
  const g = new THREE.Group();
  const kinds = { palm: [], stand: [], sign: [], balloon: [] };
  for (const d of track.decor) (kinds[d.kind] || kinds.palm).push(d);

  if (kinds.palm.length) {
    const trunk = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.32, 0.5, 7, 5),
      new THREE.MeshLambertMaterial({ color: 0x9a7b4f }), kinds.palm.length);
    const leaf = new THREE.InstancedMesh(new THREE.ConeGeometry(3.4, 2.2, 6),
      new THREE.MeshLambertMaterial({ color: 0x4f8f4a, flatShading: true }), kinds.palm.length);
    const m = new THREE.Object3D();
    kinds.palm.forEach((d, i) => {
      m.position.set(d.x, d.y + 3.5, d.z); m.rotation.set(0, i * 1.1, 0); m.updateMatrix();
      trunk.setMatrixAt(i, m.matrix);
      m.position.set(d.x, d.y + 7.4, d.z); m.updateMatrix();
      leaf.setMatrixAt(i, m.matrix);
    });
    g.add(trunk, leaf);
  }
  for (const d of kinds.stand) {
    const s = new THREE.Group();
    const tiers = 4;
    for (let i = 0; i < tiers; i += 1) {
      const row = new THREE.Mesh(new THREE.BoxGeometry(22, 1.1, 2.4),
        new THREE.MeshLambertMaterial({ color: i % 2 ? 0xf3efe1 : 0xffd166 }));
      row.position.set(0, 0.6 + i * 1.1, -i * 2.4);
      s.add(row);
    }
    const f = track.at(d.t * track.length);
    s.position.set(d.x, d.y, d.z);
    s.rotation.y = Math.atan2(f.tx, f.tz) + (d.o < 0 ? Math.PI / 2 : -Math.PI / 2);
    g.add(s);
  }
  for (const d of kinds.sign) {
    const s = new THREE.Group();
    const post = new THREE.Mesh(new THREE.BoxGeometry(0.4, 4, 0.4), new THREE.MeshLambertMaterial({ color: 0x6b5b47 }));
    post.position.y = 2;
    const board = new THREE.Mesh(new THREE.BoxGeometry(5.4, 2.2, 0.3), new THREE.MeshLambertMaterial({ color: 0x2f6b7f }));
    board.position.y = 4.6;
    s.add(post, board);
    s.position.set(d.x, d.y, d.z);
    const f = track.at(d.t * track.length);
    s.rotation.y = Math.atan2(f.tx, f.tz) + Math.PI / 2;
    g.add(s);
  }
  for (const d of kinds.balloon) {
    const b = new THREE.Mesh(new THREE.SphereGeometry(2.6, 10, 8),
      new THREE.MeshLambertMaterial({ color: 0xef6f8a }));
    b.position.set(d.x, d.y + 9, d.z);
    b.userData.float = Math.random() * 6;
    g.add(b);
  }
  // The sea, far out and flat, so the horizon is not an edge.
  const sea = new THREE.Mesh(new THREE.PlaneGeometry(2400, 2400),
    new THREE.MeshLambertMaterial({ color: 0x3f8fa8 }));
  sea.rotation.x = -Math.PI / 2;
  sea.position.y = -8;
  g.add(sea);
  return g;
}

// Item boxes: the one thing on this track that is not scenery — driving through one asks
// an English word. They spin, they bob, and they come back a few seconds after being taken.
export function itemBoxes(track) {
  const g = new THREE.Group();
  const mat = new THREE.MeshLambertMaterial({ color: 0xffd166, transparent: true, opacity: 0.92, emissive: 0x6a4b00 });
  const boxes = track.items.map((b) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(2.4, 2.4, 2.4), mat);
    m.position.set(b.x, b.y + 1.6, b.z);
    m.userData.box = b;
    g.add(m);
    return { def: b, mesh: m, takenUntil: 0 };
  });
  return { group: g, boxes };
}

export function buildTrack(track) {
  const theme = track.def;
  const root = new THREE.Group();
  const { road, kerb, land } = surfaces(track, theme);
  const ground = meshFrom(land);
  ground.receiveShadow = false;
  const tarmac = meshFrom(road);
  const kerbs = kerb.pos.length ? meshFrom(kerb) : null;
  root.add(ground, tarmac);
  if (kerbs) root.add(kerbs);
  root.add(barriers(track), startLine(track), ramps(track), pads(track), scenery(track, theme));
  return root;
}
